package com.campuskart;
import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/register") public class RegisterServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String name=v(r,"name"),sid=v(r,"studentId"),email=v(r,"email"),dept=v(r,"department"),yr=v(r,"classYear"),div=v(r,"division"),contact=v(r,"contact"),pw=r.getParameter("password");if(name.isBlank()||sid.isBlank()||email.isBlank()||dept.isBlank()||yr.isBlank()||div.isBlank()||contact.isBlank()||pw==null||pw.length()<6){s.sendRedirect("register.jsp?error=Please+fill+all+fields+and+use+a+6%2B+character+password");return;}try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO users(name,student_id,email,password_hash,department,class_year,division,contact) VALUES(?,?,?,?,?,?,?,?)")){p.setString(1,name);p.setString(2,sid);p.setString(3,email);p.setString(4,PasswordUtil.sha256(pw));p.setString(5,dept);p.setString(6,yr);p.setString(7,div);p.setString(8,contact);p.executeUpdate();s.sendRedirect("login.jsp?success=Account+created");}catch(SQLIntegrityConstraintViolationException e){s.sendRedirect("register.jsp?error=Student+ID+or+email+already+exists");}catch(SQLException e){throw new IOException(e);}}private String v(HttpServletRequest r,String n){String x=r.getParameter(n);return x==null?"":x.trim();}}